\caption{\texttt{AdaPFOL}\xspace: \textbf{Ada}ptive \textbf{P}amameter-\textbf{F}ree \textbf{O}nline \textbf{L}earning}

\begin{algorithmic}[1]
\REQUIRE{Action set $\mathcal X$. For each round $t$, the maximum loss magnitude $G_t$ will be reveled at the beginning, and a loss vector $g_t$ satisfying $\lVert g_t\rVert_\infty \le G_t$ will be given in the end.}
\STATE Set $G\gets 1$. Initialize an instance $\mathcal A$ of the algorithm in B.4 with action set $\mathcal X$.
\FOR{$t=1,2,\ldots$}
\STATE Observe the maximum loss magnitude $G_t>0$ for this round.
\IF{$G_t>G$}
\STATE Set $G=2G_t$. Reset $\mathcal A$ as a new instance of the algorithm in B.4 with action set $\mathcal X$.
\ENDIF
\STATE Output the ouptut of $\mathcal A$. Observe loss vector $g_t$ (such that $\lVert g_t\rVert_\infty\le G_t$). Feed $G^{-1}g_t$ to $\mathcal A$.
\ENDFOR
\end{algorithmic}

Consider the OLO problem in 3.3. Let the action set $\mathcal X$ has diameter $D=\sup_{x,y\in \mathcal X}\lVert x-y\rVert_1$. Suppose that $\lVert g_t\rVert_\infty\le G_t$, where $G_t$ is some $\mathcal F_{t-1}$-measurable random variable and $(\mathcal F_t)_{t=0}^T$ is the natural filtration, \textit{i.e.}, $\mathcal F_t$ is the $\sigma$-algebra generated by all random observations made during the first $t$ rounds.
Then, \texttt{AdaPFOL}\xspace (alg:OLO unbounded) ensures that for any comparator sequence $\mathring{x}_1,\mathring{x}_2,\ldots,\mathring{x}_T\in \mathcal X$, if $\max_{t\in [T]} G_t\ge 1$, then
\begin{equation*}
\text{D-Regret}_T^{\text{OLO}}(\mathring{x}_1,\mathring{x}_2,\ldots,\mathring{x}_T)=\operatorname{\mathcal O}\left (\sqrt{D \left (D+\sum_{t=1}^{T-1} \lVert \mathring{x}_t-\mathring{x}_{t+1}\rVert_1\right )}\sqrt{\sum_{t=1}^T \lVert g_t\rVert_\infty^2}\log T \log \left (\max_{t=1}^T G_t\right )\right ).
\end{equation*}

For each link $(n,m)\in {\mathcal L}$, as we did in \texttt{NSO}\xspace, we execute an instance of \texttt{AdaPFOL}\xspace (alg:OLO unbounded) where $\mathcal X=\triangle({\mathcal N})$, $g_t=C_{n,m}(t) (Q_m(t) - Q_n(t))$, and $G_t=M\lVert Q_m(t)-Q_n(t)\rVert_\infty$. We make their outputs $x_t$ as $a_{n,m}(t)$ for every round $t$. Let $\mu_{n,m}^{(k)}(t)$ be the number of actually transmitted jobs from $Q_n^{(k)}(t)$ to $Q_m^{(k)}(t+1)$ induced by $a_{n,m}^{(k)}(t)$.

Consider an arbitrary reference action sequence $\{\mathring{a} (t)\}_{t\in [T]}$ satisfying 1. Let $\mathring{\mu}_{n,m}^{(k)} (t)=C_{n,m}(t) \mathring{a}_{n,m}^{(k)} (t)\in [0,M]$ (as $C_{n,m}(t)\in [0,M]$ and $\mathring a_{n,m}^{(k)}(t)\in [0,1]$). Then
\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} (\mu_{n,m}^{(k)}(t)-\mathring{\mu}_{n,m}^{(k)}(t))\left (Q_m^{(k)}(t)-Q_n^{(k)}(t)\right )\right ]\\
&=\operatorname{\mathcal O}\left (M\sqrt{1+P_T^a} \operatornamewithlimits{\mathbb{E}}\left [\sqrt{\sum_{t=1}^T \lVert Q(t)\rVert_2^2} \log T \log \left (\max_{t=1}^T \max_{(n,m)\in {\mathcal L}} M \lVert Q_m(t) - Q_n(t)\rVert_\infty\right )\right ]\right )\text{,}
\end{align*}
where $P_T^a\triangleq \sum_{t=1}^{T-1} \sum_{(n,m)\in {\mathcal L}} \lVert \mathring{a}_{n,m}(t) - \mathring{a}_{n,m}(t+1)\rVert_1$ is the path length of $\{\mathring{a}(t)\}_{t=1}^T$.

Suppose that $\{\mathring{a}_{n,m}(t)\in \triangle({\mathcal N})\}_{(n,m)\in {\mathcal L},t\in [T]}$ satisfies 1 and its path length satisfies \footnote{This assumption on path lengths comes from [huang2023queue]. As discussed in 3, such conditions are necessary.}
\begin{equation}
P_t^a\triangleq \sum_{s=1}^{t-1} \sum_{(n,m)\in {\mathcal L}} \lVert \mathring{a}_{n,m}(s) - \mathring{a}_{n,m}(s+1)\rVert_1\le C^a t^{1/2 - \delta_a},\quad \forall t=1,2,\ldots,T,
\end{equation}
where $C^a$ and $\delta_a$ are assumed to be known constants but the precise $P_t^a$ or $\{\mathring{a}_{n,m}(t)\in \triangle({\mathcal N})\}_{(n,m)\in {\mathcal L},t\in [T]}$ both remain unknown.
Then, if we execute the \texttt{NSO}\xspace framework in alg:stability with \texttt{AdaPFOL}\xspace defined in alg:OLO unbounded, the following performance guarantee is enjoyed:
\begin{equation*}
\frac 1T\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2(2NM+R)^2 + \epsilon_W N^2 (2NM+R))C_W + (N^4 M^2 + N^2 R^2)}{\epsilon_W}\right )+o_T(1).
\end{equation*}
That is, when $T\gg 0$, we have $\frac{1}{T} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T(1)$, \textit{i.e.}, 2 holds and the system is stable.

Under the queue dynamics of 1,
\begin{align*}
&\quad -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} C_{n,m}(t) (Q_m^{(k)}(t)-Q_n^{(k)}(t))a_{n,m}^{(k)}(t)\right ] \\
&\quad -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \lambda_n^{(k)}(t)\right ]+V \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (g_t(\lambda(t))-g_t(\mathring{\lambda}(t)))\right ] \\
&\le \frac 12 N^2 ((NM)^2+2(NM)^2+2R^2)T +V  \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (g_t(\lambda(t))-g_t(\mathring{\lambda}(t)))\right ].
\end{align*}

\caption{\texttt{AdaBGD}\xspace: \textbf{A}daptive \textbf{B}andit \textbf{G}radient \textbf{D}escent}

\begin{algorithmic}[1]
\REQUIRE{Action set $\mathcal X$ bounded by $[r,R]$ (\textit{i.e.}, $r\mathbb B\subseteq \mathcal X\subseteq R\mathbb B$), hyper-parameters $\eta_1>\eta_2>\cdots>\eta_T$, $\delta_1,\delta_2,\ldots,\delta_T$, and $\alpha_t\triangleq \delta_t / r,\forall t\in [T]$.}
\STATE Initialize $y_1=0$ (an internal variable of the algorithm).
\FOR{$t=1,2,\ldots,T$}
\STATE Calculate this round's action $x_t\in \mathcal X$, observe loss $\ell_t(x_t)$, and update internal variable $y_{t+1}$:
\begin{equation}
x_t=y_t+\delta s_t,\quad y_{t+1}=\text{Proj}_{(1-\alpha_t)\mathcal X}\left [y_t-\eta_t \frac{d}{\delta_t} \ell_t(x_t) s_t\right ],
\end{equation}
where $s_t\in \mathbb R^d$ is a uniformly sampled unit vector used to estimate gradients [flaxman2005online].
\ENDFOR
\end{algorithmic}

Suppose that $r\mathbb B\subseteq \mathcal X\subseteq R\mathbb B$, the $t$-th loss $\ell_t$ is bounded by $C_t$ and is $L_t$-Lipschitz.
Suppose that $\eta_t$ and $\delta_t$ are both $\mathcal F_{t-1}$-measurable (where $(\mathcal F_t)_{t=0}^T$ is the natural filtration), $\eta_1>\eta_2>\cdots>\eta_T$, and $\alpha_t\triangleq \delta_t / r<1$ \textit{a.s.} for all $t\in [T]$. Then for any fixed $u_1,u_2,\ldots,u_T\in \mathcal X$, the \texttt{AdaBGD}\xspace algorithm in alg:ABGD enjoys the following guarantee:
\begin{align*}
&\quad \text{D-Regret}_T^{\text{BCO}}(u_1,u_2,\ldots,u_T)=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(x_t)-\ell_t(u_t))\right ]\\
&\le \operatornamewithlimits{\mathbb{E}}\left [\frac{7R^2}{4\eta_T}+\frac{P_T R}{\eta_T}+\sum_{t=1}^T \left (\frac{\eta_t}{2} \frac{d^2}{\delta_t^2} C_t^2 + 3L_t \delta_t + L_t \alpha_t R\right )\right ],
\end{align*}
where $P_T=\sum_{t=1}^{T-1}\lVert u_t-u_{t+1}\rVert$ is the path length of the comparator sequence $\{u_t\}_{t\in [T]}$.

For the reference arrival rates $\{\mathring{\lambda}(t)\}_{t\in [T]}$ defined in 2, suppose that its path length ensures
\begin{equation*}
P_t^\lambda\triangleq \sum_{t=1}^{T-1} \lVert \mathring{\lambda}({t+1}) - \mathring{\lambda}(t)) \rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t=1,2,\ldots,T,
\end{equation*}
where, similar to 3.6, $C^\lambda$ and $\delta_\lambda$ are assumed to be known constants but the precise $P_t^\lambda$ or $\{\mathring{\lambda}(t)\}_{t\in [T]}$ both remain unknown.
Suppose that the action set $\Lambda$ is bounded by $[r,R]$ (\textit{i.e.}, $r\mathbb B\subseteq \Lambda\subseteq R\mathbb B$).
If we execute \texttt{AdaBGD}\xspace (alg:ABGD) over $\Lambda$ with loss functions $\ell_t(\lambda)=\langle Q(t),\lambda\rangle-V g_t(\lambda)$ and parameters $\eta_t,\delta_t,\alpha_t$ defined in 11 (restated below as 18 to ease reading):
\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert q_s\rVert_\infty + VG)^2 (\lVert q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert Q(t)\rVert_\infty + VG)^2}{(\lVert Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r},
\end{align}
then the outputs $\lambda(1),\lambda(2),\ldots,\lambda(T) \in \Lambda$ of \texttt{AdaBGD}\xspace ensure
\begin{align*}
